const clients = ($('Fetch All Clients').first().json.data || []);
const vacancies = ($('Fetch All Vacancies').first().json.data || []);
const applications = ($('Fetch All Applications').first().json.data || []);

const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);

const results = [];
for (const client of clients) {
  const clientId = client.id;
  const clientVacancies = vacancies.filter(v => v.clientId === clientId);
  const vacancyTitles = clientVacancies.map(v => v.title || '').join(', ');
  const clientApps = applications.filter(a => a.clientId === clientId);
  const newApps = clientApps.filter(a => {
    try { return new Date(a.createdAt) >= weekAgo; } catch(e) { return false; }
  });

  results.push({
    json: {
      client_id: clientId,
      client_name: client.companyName || 'Onbekend',
      active_vacancies: clientVacancies.length,
      vacancy_titles: vacancyTitles || 'geen',
      total_applications: clientApps.length,
      new_applications: newApps.length,
      prompt: `Je bent de account manager bij Top Match. Schrijf een kort weekrapport (3-5 zinnen, professioneel Nederlands) voor de klant.\n\nKlant: ${client.companyName}\nActieve vacatures: ${clientVacancies.length}\nVacature-titels: ${vacancyTitles || 'geen'}\nNieuwe sollicitaties deze week: ${newApps.length}\nTotaal sollicitaties: ${clientApps.length}\n\nAls er weinig activiteit is, stel dan proactief een actie voor.\n\nAntwoord als JSON:\n{\n  "summary": "het rapport",\n  "status": "on_track|needs_attention|urgent",\n  "suggested_actions": ["actie 1", "actie 2"]\n}`
    }
  });
}

return results.length > 0 ? results : [{json: {error: 'Geen klanten gevonden'}}];

const items = $input.all();
const clientItems = $('Build Per-Client Summaries').all();
const statusIcons = { on_track: '🟢', needs_attention: '🟡', urgent: '🔴' };

const now = new Date();
let digest = `📊 *Top Match — Wekelijks Klantenoverzicht*\n📅 ${now.toLocaleDateString('nl-NL')}\n${'='.repeat(40)}\n\n`;

const reports = [];
for (let i = 0; i < items.length; i++) {
  const client = clientItems[i]?.json || {};
  let report;
  try {
    const text = items[i].json.content?.[0]?.text || '{}';
    report = JSON.parse(text);
  } catch (e) {
    report = { summary: items[i].json.content?.[0]?.text || 'Geen rapport', status: 'on_track', suggested_actions: [] };
  }

  const icon = statusIcons[report.status] || '⚪';
  digest += `${icon} *${client.client_name}*\n`;
  digest += `   ${report.summary}\n`;
  if (report.suggested_actions && report.suggested_actions.length > 0) {
    digest += `   Acties:\n`;
    for (const action of report.suggested_actions) {
      digest += `   • ${action}\n`;
    }
  }
  digest += '\n';

  reports.push({
    client_id: client.client_id,
    client_name: client.client_name,
    ...report
  });
}

return [{json: {digest, reports, generated_at: now.toISOString()}}];
